Validate the URL against an allowlist of permitted hosts and schemes before making the request:

```python
ALLOWED_HOSTS = {"api.partner1.com", "api.partner2.com"}

@app.route("/fetch")
def fetch_url():
    url = request.args.get("url", "")
    parsed = urlparse(url)
    if parsed.scheme not in ("http", "https"):
        return "Invalid scheme", 400
    if parsed.hostname not in ALLOWED_HOSTS:
        return "Host not allowed", 403
    response = requests.get(url, timeout=5)
    return response.text
```
Also consider blocking private/link-local IP ranges even when using an allowlist, and prefer IMDSv2 token-based access on AWS to mitigate metadata endpoint abuse.

Validate `target_url` against an allowlist of permitted hosts and enforce scheme restrictions before forwarding the request:

```python
ALLOWED_WEBHOOK_HOSTS = {"hooks.partner1.com", "hooks.partner2.com"}

@app.route("/webhook-proxy", methods=["POST"])
def webhook_proxy():
    data = request.json
    target = data.get("target_url", "")
    payload = data.get("payload")
    parsed = urlparse(target)
    if parsed.scheme not in ("http", "https"):
        return {"error": "Invalid scheme"}, 400
    if parsed.hostname not in ALLOWED_WEBHOOK_HOSTS:
        return {"error": "Host not allowed"}, 403
    requests.post(target, json=payload, timeout=10)
    return {"status": "sent"}
```

Never deserialize pickle data from untrusted sources. Use a safe, structured format such as JSON instead:

```python
import json

@app.route("/restore-session", methods=["POST"])
def restore_session():
    raw = request.form.get("session_blob", "{}")
    session_data = json.loads(raw)  # JSON cannot execute code
    return {"restored": list(session_data.keys())}
```

If pickle is absolutely required for internal use, sign the payload with an HMAC using a secret key and verify the signature before deserializing:

```python
import hmac, hashlib, pickle

SECRET = b"<strong-random-secret>"

def safe_loads(signed_blob):
    sig, data = signed_blob[:32], signed_blob[32:]
    expected = hmac.new(SECRET, data, hashlib.sha256).digest()
    if not hmac.compare_digest(sig, expected):
        raise ValueError("Invalid signature")
    return pickle.loads(data)
```

